import os
import sqlite3
from datetime import datetime, timezone
import requests
GRAPH_API_BASE = 'https://graph.facebook.com/v21.0'
LOG_DB_PATH = '/var/lib/social-suite/community.db'


def _discard_reply_drafts(connection, comment_id: str) -> int:
    # Once a reply is published, any saved drafts for this comment are obsolete;
    # permanently remove them so they don't reappear in the moderators' queue.
    cursor = connection.execute('DELETE FROM reply_drafts WHERE comment_id = ?', (comment_id,))
    return cursor.rowcount


def reply_to_instagram_comment(comment_id: str, reply_text: str) -> dict:
    if not comment_id or not comment_id.isdigit():
        return {'ok': False, 'error': 'comment_id must be a numeric Instagram comment ID'}
    message = (reply_text or '').strip()
    if not message:
        return {'ok': False, 'error': 'reply_text cannot be empty'}
    if len(message) > 2200:
        return {'ok': False, 'error': 'reply_text exceeds 2200 characters'}
    response = requests.post(f'{GRAPH_API_BASE}/{comment_id}/replies', data={'message': message, 'access_token': os.environ['IG_PAGE_ACCESS_TOKEN']}, timeout=15)
    if response.status_code != 200:
        return {'ok': False, 'status_code': response.status_code, 'error': response.text[:500]}
    reply_id = response.json().get('id')
    with sqlite3.connect(LOG_DB_PATH) as connection:
        connection.execute('INSERT INTO comment_replies (comment_id, reply_id, reply_text, replied_at) VALUES (?, ?, ?, ?)', (comment_id, reply_id, message, datetime.now(timezone.utc).isoformat()))
        connection.execute("UPDATE inbox_comments SET status = 'handled' WHERE comment_id = ?", (comment_id,))
        drafts_removed = _discard_reply_drafts(connection, comment_id)
    return {'ok': True, 'reply_id': reply_id, 'drafts_removed': drafts_removed}
